INSERT INTO notifications(notification_id,user_id,source,type,subscription_id,title,body,payload_json,created_at,read) VALUES ('ntf_7492dcd26f','hanqi_rental','listing_platform','keyword','sub_home_status','收藏房源状态变化','本次更新包括以下内容：芍药居北里的一套房源恢复可租，经纪人开放了本周末两个看房时段。 芍药居北里收藏记录没有覆盖旧的下架时间。—本次更新时间已写入详情。','{"topic":"rent","reference":"WO-2B5E752D","source_time":"2026-02-01T11:46:00+08:00","district":"朝阳区"}','2026-02-01T11:46:00+08:00',1);
INSERT INTO notifications(notification_id,user_id,source,type,subscription_id,title,body,payload_json,created_at,read) VALUES ('ntf_e7ac499738','hanqi_rental','community_service','policy_update',NULL,'社区停水通知','在2026-02-08的记录中，万泉新新家园将在2026-02-08上午清洗水箱，预计停水两小时，恢复后先排放少量存水。 万泉新新家园清洗水箱的时段已同步到社区账号。—本次更新时间已写入详情。','{"topic":"repair","reference":"WO-607DAB5C","source_time":"2026-02-08T14:03:00+08:00","district":"海淀区"}','2026-02-08T14:03:00+08:00',0);
